export function solve(input) {
  const d = input;
  const valid = d.type === "integer" ? Number.isSafeInteger(d.value) : typeof d.value === "string";
  if (!valid) return ["type"];
  const n = d.type === "string" ? d.value.length : d.value;
  const out = [];
  if (d.min !== undefined && n < d.min) out.push("min");
  if (d.max !== undefined && n > d.max) out.push("max");
  return out;
}

